#!/usr/bin/env tsx
/**
 * Generates env.sh from app-config.json (the source of truth for frontend settings). Every property
 * in specs/app-config.schema.json that declares an `x-envVar` becomes one export. The generated
 * file ends by sourcing env.defaults.sh, which holds every project default that is not generated.
 * Run: yarn sync:env
 *
 * env.sh is a generated artifact; do not edit it by hand. Update app-config.json, the schema or
 * env.defaults.sh.
 */

import * as fs from 'node:fs';
import * as path from 'node:path';

const commandName = 'sync:env';

const configFilePath = path.resolve('app-config.json');
const schemaFilePath = path.resolve('specs/app-config.schema.json');
const outputFilePath = path.resolve('env.sh');

type SchemaNode = {
  properties?: Record<string, SchemaNode>;
  required?: string[];
  'x-envVar'?: string;
};

type EnvVariableMapping = {
  name: string;
  sourcePath: string;
  isRequired: boolean;
};

type EnvVariableGroup = {
  sectionName: string;
  variables: EnvVariableMapping[];
};

const fileHeaderComments = [
  'Generated by `yarn sync:env` from app-config.json and the x-envVar mappings in',
  'specs/app-config.schema.json. Do not edit by hand; changes are overwritten on the next sync.',
  'Project defaults that are not generated live in env.defaults.sh, sourced at the end of this file.',
];

// Resolved from this file's own location, so env.sh can be sourced from any directory (bash only).
const defaultsImportLine = 'source "$(dirname "${BASH_SOURCE[0]}")/env.defaults.sh"';

// Translates a shared config value to what the web app expects when the enums differ.
const valueMapsByEnvVariable: Record<string, Record<string, string>> = {
  // Schema enum is 'activeSpeaker'; the web app expects 'active-speaker'.
  DEFAULT_LAYOUT_MODE: { activeSpeaker: 'active-speaker' },
};

const listSeparator = '|';

const environmentOnlyVariableNames = new Set(['API_URL', 'TUNNEL_DOMAIN', 'VONAGE_VIDEO_HOST']);

function readJsonFile<Content>(filePath: string): Content {
  if (!fs.existsSync(filePath)) {
    console.error(`\x1b[31m✖ File not found at ${filePath}\x1b[0m`);
    process.exit(1);
  }

  const raw = fs.readFileSync(filePath, 'utf-8');

  try {
    return JSON.parse(raw) as Content;
  } catch (error) {
    console.error(`\x1b[31m✖ Failed to parse ${filePath} as JSON\x1b[0m`, error);
    process.exit(1);
  }
}

function collectEnvVariableMappings(args: {
  node: SchemaNode;
  parentPath: string[];
  isParentRequired: boolean;
}): EnvVariableMapping[] {
  return Object.entries(args.node.properties ?? {}).flatMap(([key, childNode]) => {
    const childPath = [...args.parentPath, key];
    const isRequired = args.isParentRequired && (args.node.required ?? []).includes(key);
    const envVariableName = childNode['x-envVar'];
    const ownMapping = envVariableName
      ? [{ name: envVariableName, sourcePath: childPath.join('.'), isRequired }]
      : [];

    return [
      ...ownMapping,
      ...collectEnvVariableMappings({
        node: childNode,
        parentPath: childPath,
        isParentRequired: isRequired,
      }),
    ];
  });
}

function groupBySection(mappings: EnvVariableMapping[]): EnvVariableGroup[] {
  const groups = new Map<string, EnvVariableMapping[]>();

  for (const mapping of mappings) {
    const [sectionName] = mapping.sourcePath.split('.');
    groups.set(sectionName, [...(groups.get(sectionName) ?? []), mapping]);
  }

  return [...groups].map(([sectionName, variables]) => ({ sectionName, variables }));
}

function resolvePath(config: Record<string, unknown>, sourcePath: string): unknown {
  return sourcePath.split('.').reduce<unknown>((current, key) => {
    if (current === null || typeof current !== 'object') return undefined;
    return (current as Record<string, unknown>)[key];
  }, config);
}

function escapeSingleQuoted(value: string): string {
  return value.replaceAll("'", String.raw`'\''`);
}

function serializeValue(value: unknown): string {
  if (Array.isArray(value)) return `'${escapeSingleQuoted(value.join(listSeparator))}'`;
  if (typeof value === 'string') return `'${escapeSingleQuoted(value)}'`;
  return String(value);
}

function resolveValue(mapping: EnvVariableMapping, config: Record<string, unknown>): unknown {
  const value = resolvePath(config, mapping.sourcePath);

  if (value === undefined && mapping.isRequired) {
    console.error(
      `\x1b[31m✖ Missing value in app-config.json for path "${mapping.sourcePath}"\x1b[0m`
    );
    process.exit(1);
  }

  const valueMap = valueMapsByEnvVariable[mapping.name];

  if (valueMap && typeof value === 'string' && value in valueMap) {
    return valueMap[value];
  }

  return value;
}

function buildGroupBlock(group: EnvVariableGroup, config: Record<string, unknown>): string | null {
  const exportLines = group.variables.flatMap((mapping) => {
    const value = resolveValue(mapping, config);
    if (value === undefined) return [];
    return [`export ${mapping.name}=${serializeValue(value)}`];
  });

  if (exportLines.length === 0) return null;

  return [`# ${group.sectionName}`, ...exportLines].join('\n');
}

function buildEnvFileContents(args: {
  config: Record<string, unknown>;
  schema: SchemaNode;
}): string {
  const mappings = collectEnvVariableMappings({
    node: args.schema,
    parentPath: [],
    isParentRequired: true,
  }).filter((mapping) => !environmentOnlyVariableNames.has(mapping.name));
  const groups = groupBySection(mappings);
  const groupBlocks = groups
    .map((group) => buildGroupBlock(group, args.config))
    .filter((block): block is string => block !== null);

  const header = ['#!/bin/bash', ...fileHeaderComments.map((comment) => `# ${comment}`)].join('\n');

  return `${[header, ...groupBlocks, defaultsImportLine].join('\n\n')}\n`;
}

const generateEnv = () => {
  console.log(`\x1b[36m🔄 [${commandName}] Generating env.sh from app-config.json\x1b[0m\n`);

  const config = readJsonFile<Record<string, unknown>>(configFilePath);
  const schema = readJsonFile<SchemaNode>(schemaFilePath);
  const contents = buildEnvFileContents({ config, schema });

  fs.writeFileSync(outputFilePath, contents, 'utf-8');

  console.log(`\x1b[32m✔ [${commandName}] Wrote ${outputFilePath}\x1b[0m`);
};

generateEnv();
